<?phprequire_once './token.php';if ($token != $_POST['token']) {    die;}repairCategories(0);// Function to repair any erroneous categories that are not in the category path table.function repairCategories($parent_id){    require_once '../config.php';    $conexion = mysqli_connect(DB_HOSTNAME, DB_USERNAME, DB_PASSWORD) or die('Error');    mysqli_set_charset($conexion, 'utf8');    mysqli_select_db($conexion, DB_DATABASE);    $result = mysqli_query($conexion, 'SELECT * FROM ' . DB_PREFIX . 'category WHERE parent_id = \'' . (int) $parent_id . '\'');    while ($row = mysqli_fetch_array($result)) {        $category = $row['category_id'];        // Delete the path below the current one        $result2 = mysqli_query($conexion, 'DELETE FROM `' . DB_PREFIX . 'category_path` WHERE category_id = \'' . (int) $category . '\'');        // Fix for records with no paths        $level = 0;        $result2 = mysqli_query($conexion, 'SELECT * FROM `' . DB_PREFIX . 'category_path` WHERE category_id = \'' . (int) $parent_id . '\' ORDER BY level ASC');        while ($row2 = mysqli_fetch_array($result2)) {            $path_id = $row2['path_id'];            $result3 = mysqli_query($conexion, 'INSERT INTO `' . DB_PREFIX . 'category_path` SET category_id = \'' . (int) $category . '\', `path_id` = \'' . (int) $path_id . '\', level = \'' . (int) $level . '\'');            $level++;        }        $result2 = mysqli_query($conexion, 'REPLACE INTO `' . DB_PREFIX . 'category_path` SET category_id = \'' . (int) $category . '\', `path_id` = \'' . (int) $category . '\', level = \'' . (int) $level . '\'');        repairCategories($category);    }}?>
